import java.nio.file.*;import java.util.*;import com.kingofcards.identity.maintenance.Safety;
public class DetachFixtureChild {
    public static void main(String[]args)throws Exception{Path root=Path.of(args[0]);Runtime.getRuntime().addShutdownHook(new Thread(()->{try{Files.writeString(root.resolve("graceful.marker"),"shutdown hook completed",StandardOpenOption.CREATE_NEW);}catch(Exception e){throw new RuntimeException(e);}}));Files.writeString(root.resolve("ready.marker"),"fixture ready",StandardOpenOption.CREATE_NEW);var seen=new HashSet<String>();while(true){try(var files=Files.list(root)){for(Path p:files.filter(f->f.toString().endsWith(".stop-request")).toList()){if(!seen.add(p.toString()))continue;var ack=Safety.load(root.resolve("detached.properties"));long caller=Long.parseLong(ack.getProperty("callerPid"));try{Safety.detached(ack,"fixture",ProcessHandle.of(caller).filter(ProcessHandle::isAlive).isPresent());System.exit(0);}catch(IllegalStateException refused){Files.writeString(root.resolve("refused.marker"),"caller still alive",StandardOpenOption.CREATE_NEW);}}}Thread.sleep(50);}}
}
